17: - (void)handleMemoryWarning:(NSNotification *)notification {
18:     // Clear URL caches
19:     [[NSURLCache sharedURLCache] removeAllCachedResponses];
20: 
21:     // Clear temporary files
22:     NSString *tmpDir = NSTemporaryDirectory();
23:     NSFileManager *fm = [NSFileManager defaultManager];
24:     NSArray *tmpFiles = [fm contentsOfDirectoryAtPath:tmpDir error:nil];
25:     for (NSString *file in tmpFiles) {
26:         NSString *path = [tmpDir stringByAppendingPathComponent:file];
27:         [fm removeItemAtPath:path error:nil];
28:     }
