9:     if ([scene isKindOfClass:[UIWindowScene class]]) {
10:         UIWindowScene *windowScene = (UIWindowScene *)scene;
11:         self.window = [[UIWindow alloc] initWithWindowScene:windowScene];
12:         
13:         Class filePickerClass = NSClassFromString(@"ReDyne.FilePickerViewController");
14:         if (filePickerClass) {
15:             id rootViewController = [[filePickerClass alloc] init];
16:             [rootViewController performSelector:@selector(setSceneDelegate:) withObject:self];
17:             UINavigationController *navigationController = [[UINavigationController alloc] initWithRootViewController:rootViewController];
18:             UINavigationBarAppearance *appearance = [[UINavigationBarAppearance alloc] init];
19:             [appearance configureWithDefaultBackground];
20:             navigationController.navigationBar.standardAppearance = appearance;
21:             navigationController.navigationBar.scrollEdgeAppearance = appearance;
22:             navigationController.navigationBar.prefersLargeTitles = YES;
23:             
24:             self.window.rootViewController = navigationController;
25:             [self.window makeKeyAndVisible];
26:         } else {
27:             NSLog(@"ERROR: Could not find FilePickerViewController class!");
28:             UIViewController *errorVC = [[UIViewController alloc] init];
29:             errorVC.view.backgroundColor = [UIColor systemRedColor];
30:             UILabel *label = [[UILabel alloc] initWithFrame:CGRectMake(20, 100, 300, 200)];
31:             label.text = @"Error: FilePickerViewController not found!\n\nCheck if Swift files are compiled.";
32:             label.numberOfLines = 0;
33:             label.textColor = [UIColor whiteColor];
34:             label.textAlignment = NSTextAlignmentCenter;
35:             [errorVC.view addSubview:label];
36:             
37:             self.window.rootViewController = errorVC;
